java.source:
import software.amazon.awscdk.services.lambda.*;
import ashishpandeyone.cdk.lambda.web.function.WebFunction;
import ashishpandeyone.cdk.lambda.web.function.WebFunctionAuthType;
import ashishpandeyone.cdk.lambda.web.function.WebFunctionEndpointType;


WebFunction fn = WebFunction.Builder.create(this, "Api")
        .runtime(Runtime.NODEJS_24_X)
        .code(Code.fromAsset("dist"))
        .authType(WebFunctionAuthType.AWS_IAM)
        .endpoint(WebFunctionEndpointOptions.builder()
                .endpointType(WebFunctionEndpointType.MULTI_REGION)
                .regions(List.of("us-east-1", "eu-west-1"))
                .build())
        .build();

CfnOutput.Builder.create(this, "Url").value(fn.getEndpoint().getUrl()).build();

